import{_ as o,o as a,c as t,a3 as c}from"./chunks/framework.B8jMSdkO.js";const h=JSON.parse('{"title":"Crate map — cypera","description":"","frontmatter":{},"headers":[],"relativePath":"reference/crate-map.md","filePath":"reference/crate-map.md"}'),r={name:"reference/crate-map.md"};function s(d,e,n,i,p,l){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="crate-map-—-cypera" tabindex="-1">Crate map — <code>cypera</code> <a class="header-anchor" href="#crate-map-—-cypera" aria-label="Permalink to &quot;Crate map — `cypera`&quot;">​</a></h1><table tabindex="0"><thead><tr><th>crate</th><th>layer</th><th>purpose</th></tr></thead><tbody><tr><td><code>cypera-core</code></td><td>domain</td><td>Pure domain logic for cypera — doc-generation models and markdown renderers</td></tr><tr><td><code>cypera-driver</code></td><td>driver</td><td>tamias-driver-cypera — pavo driver exposing a cypera workspace&#39;s engine ops (no views)</td></tr><tr><td><code>cypera-xtask</code></td><td>tooling</td><td>Workspace automation — check / test / coverage / pack / install / fmt</td></tr><tr><td><code>cypera</code></td><td>binary</td><td>cypera — reusable documentation/reference generation for the 9aia org.</td></tr></tbody></table><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;Modules&quot;">​</a></h2><h3 id="cypera-core" tabindex="-1"><code>cypera-core</code> <a class="header-anchor" href="#cypera-core" aria-label="Permalink to &quot;`cypera-core`&quot;">​</a></h3><p>cypera-core — pure domain for cypera, the org&#39;s reusable documentation/reference-generation tool.</p><p>Everything here is string/AST-shape in, markdown out — <strong>no I/O</strong>. <code>cypera-cli</code> owns filesystem walks, process spawning, and stdout; this crate owns the models and the renderers:</p><ul><li>[<code>manifest</code>] — <code>Cargo.toml</code> decoding (workspace members + per-crate manifests).</li><li>[<code>crate_map</code>] — the crate-map model + markdown renderer (successor to the per-repo <code>docs/gen-crate-map.py</code> scripts).</li><li>[<code>config</code>] — Rust config-struct doc-comment scanning + the config-reference page renderer (successor to <code>docs/gen-config-docs.py</code>).</li><li>[<code>cli</code>] — the CLI-reference page wrapper for <code>gen-cli-docs</code> output (the <code>clap-markdown</code> markdown sibling CLIs emit).</li></ul><p>Modules: <code>api</code>, <code>cli</code>, <code>config</code>, <code>crate_map</code>, <code>error</code>, <code>manifest</code>, <code>repo_config</code>. Entry: <code>src/lib.rs</code>.</p><h3 id="cypera-driver" tabindex="-1"><code>cypera-driver</code> <a class="header-anchor" href="#cypera-driver" aria-label="Permalink to &quot;`cypera-driver`&quot;">​</a></h3><p>tamias-driver-cypera — the pavo driver for a cypera workspace, plus the engine ops surface.</p><p>Verbs (the tamias driver contract):</p><ul><li><code>manifest</code> — print the [<code>DriverManifest</code>] JSON (discovery probe; never touches workspace state).</li><li><code>capabilities</code> — <code>{&quot;capabilities&quot;: [&quot;pavo&quot;], &quot;verbs&quot;: […]}</code>.</li><li><code>ops</code> — the engine ops manifest: every bounded <code>cypera</code> CLI verb as a <code>cli.&lt;verb&gt;</code> wire query, derived from the engine&#39;s own clap tree ([<code>cypera::command</code>]). Unbounded/host-interactive verbs are <code>surfaces</code>, never ops (cypera has none today).</li><li><code>run &lt;argv&gt;</code> — engine passthrough: <code>tamias-driver-cypera run check</code> ≡ <code>cypera check</code>. Also the child side of <code>cli.*</code> wire queries (<code>ops::run_verb</code> re-execs this same verb so engine output never touches the serve stream).</li><li><code>cli &lt;cypera argv&gt;</code> — the tamias <code>bins[]</code> shim verb: <code>tamias bin exec</code> calls it with the standard <code>--dir</code>/<code>--name</code> driver flags ahead of the user&#39;s argv; they&#39;re stripped and the rest runs through <code>cypera::run_from</code> in-process with inherited stdio — full engine parity (<code>--help</code>/<code>version</code>, globals, <code>--json</code>, stdin-bound flags all work).</li><li><code>serve</code> — ndjson JSON-RPC on stdio: <code>{&quot;op&quot;:&quot;manifest&quot;}</code>, <code>{&quot;op&quot;:&quot;views&quot;}</code>, <code>{&quot;op&quot;:&quot;view&quot;,&quot;view&quot;:…,&quot;params&quot;:{…}}</code>, <code>{&quot;op&quot;:&quot;query&quot;,&quot;query&quot;:…,&quot;params&quot;:{…}}</code> → <code>{&quot;ok&quot;:true,&quot;result&quot;:…}</code> / <code>{&quot;ok&quot;:false,&quot;error&quot;:…}</code>. <code>query:&quot;ops&quot;</code> answers the ops manifest; <code>query:&quot;cli.&lt;verb&gt;&quot;</code> runs the engine op.</li></ul><p>Optional surface: feature <code>mcp</code> embeds pavo-driver-kit&#39;s surface layer — <code>mcp</code> serves the ops manifest as MCP tools on stdio, equivalent to the standalone <code>tamias-driver-mcp</code> surface driver minus the PATH/discovery hop. (<code>cli</code> needs no feature: it&#39;s the bins-shim passthrough above, not a generated surface — the engine&#39;s own argv grammar is the contract.)</p><p>Which repo: ops inherit the <code>serve</code> process&#39;s cwd — each verb&#39;s <code>--repo</code>/<code>--config</code> params map straight onto the engine&#39;s own flags, and absent them <code>cypera</code>&#39;s upward <code>cypera.toml</code> discovery applies, identical to running the <code>cypera</code> verb by hand. This driver ships no views — it is the engine-ops surface for cypera workspaces; view/query names outside <code>ops</code>/<code>cli.*</code> answer <code>ok:false</code>.</p><p>Modules: <code>ops</code>, <code>surface</code>. Entry: <code>src/main.rs</code>.</p><h3 id="cypera-xtask" tabindex="-1"><code>cypera-xtask</code> <a class="header-anchor" href="#cypera-xtask" aria-label="Permalink to &quot;`cypera-xtask`&quot;">​</a></h3><p>cypera-xtask — workspace automation: check / test / coverage / pack / install / fmt.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cargo xtask check      # fmt --check + clippy -D warnings</span></span>\n<span class="line"><span>cargo xtask test       # cargo nextest run (falls back to cargo test)</span></span>\n<span class="line"><span>cargo xtask coverage   # llvm-cov report (extra args pass through)</span></span>\n<span class="line"><span>cargo xtask pack       # stage libraries/cypera driver payload</span></span>\n<span class="line"><span># (release tamias-driver-cypera → drivers/bin/&lt;triple&gt;/)</span></span>\n<span class="line"><span>cargo xtask install    # release-build tamias-driver-cypera → ~/.local/bin</span></span>\n<span class="line"><span>cargo xtask fmt        # cargo fmt --all</span></span></code></pre></div><p>No module declarations. Entry: <code>src/main.rs</code>.</p><h3 id="cypera" tabindex="-1"><code>cypera</code> <a class="header-anchor" href="#cypera" aria-label="Permalink to &quot;`cypera`&quot;">​</a></h3><p>cypera — reusable documentation/reference generation for the 9aia org. The shared successor to the per-repo <code>docs/gen-*.py</code> scripts: one tool renders the crate map, CLI reference, and config reference pages every sibling docs site needs, driven by a per-repo <code>cypera.toml</code> discovered upward from <code>--repo</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cypera gen crate-map [--repo &lt;path&gt;] [--config &lt;path&gt;] [--out &lt;file&gt;] [--layer &lt;crate=layer&gt;]…</span></span>\n<span class="line"><span>cypera gen cli       [--repo &lt;path&gt;] [--config &lt;path&gt;] [--input &lt;file|-&gt;] [--out &lt;file&gt;]</span></span>\n<span class="line"><span>cypera gen config    [--repo &lt;path&gt;] [--config &lt;path&gt;] [--file &lt;rs&gt;]… [--out &lt;file&gt;]</span></span>\n<span class="line"><span>cypera gen api       [--repo &lt;path&gt;] [--config &lt;path&gt;] [--out &lt;dir&gt;] [--target-dir &lt;dir&gt;]</span></span>\n<span class="line"><span>cypera check         [--repo &lt;path&gt;] [--config &lt;path&gt;] [--json]</span></span></code></pre></div><p>All generation logic lives in <code>cypera-core</code> (pure); this crate owns argv, <code>cypera.toml</code> discovery, filesystem walks, process spawning, and stdout.</p><p>Modules: <code>check</code>. Entry: <code>src/lib.rs</code>.</p>',24)])])}const g=o(r,[["render",s]]);export{h as __pageData,g as default};
